"常":{"k":"常 떳떳할 상","r":"巾","p":["尚","巾"],"o":"뜻은 巾(수건 건), 소리는 尚(shàng)에서 온 형성자.","m":"천(巾)을 늘 숭상(尚)하니 — 늘, 항상.","lv":1},
