"高":{"k":"高 높을 고","r":"高","p":["亠","口","冋"],"o":"높은 누각 건물 모양.","m":"지붕, 창, 문이 층층이 쌓인 높은 건물.","lv":1},
"兴":{"k":"興 일 흥","r":"八","p":["⺍","一","八"],"o":"여러 손이 함께 물건을 들어 올리는 모양 → 일으키다, 흥겹다.","m":"모두 함께 번쩍 들어 올리니 흥(兴)이 난다.","lv":1},
"哥":{"k":"哥 형 가","r":"口","p":["可"],"o":"可를 두 번 겹친 글자.","m":"'옳지(可) 옳지(可)' 하는 형님.","lv":1},
