"菜":["","妈妈做的菜很好吃。","엄마가 만든 요리는 아주 맛있어요.","Māma zuò de cài hěn hǎochī."],
"茶":["","你喝茶吗？","차 마실래요?","Nǐ hē chá ma?"],
"唱":["","她很喜欢唱歌。","그녀는 노래하는 걸 아주 좋아해요.","Tā hěn xǐhuan chàng gē."],
