"大学":["大(큰) + 学(배움) → 큰 배움의 곳 = 대학","我哥哥在北京上大学。","우리 형은 베이징에서 대학에 다녀요.","Wǒ gēge zài běi jīng shàng dàxué."],
"大学生":["大学(대학) + 生(학생) → 대학생","她是大学生。","그녀는 대학생이에요.","Tā shì dàxuéshēng."],
